import {useQuery} from '@github-ui/react-query'
import {verifiedFetch} from '@github-ui/verified-fetch'
import type {CustomModelsIndexPayload} from '../types'

export const getCustomModelsQueryKey = (enterpriseSlug: string) => ['byok-settings', 'customModels', enterpriseSlug]

export function useCustomModelsQuery({
  enterpriseSlug,
  initialData,
}: {
  enterpriseSlug: string
  initialData: Partial<CustomModelsIndexPayload>
}) {
  return useQuery({
    queryKey: getCustomModelsQueryKey(enterpriseSlug),
    queryFn: async (): Promise<CustomModelsIndexPayload> => {
      const response = await verifiedFetch(`/enterprises/${enterpriseSlug}/settings/copilot/custom-models`, {
        headers: {Accept: 'application/json'},
      })
      if (!response.ok) {
        throw new Error(`Failed to fetch Copilot custom models for enterprise ${enterpriseSlug}: ${response.status}`)
      }
      const result = await response.json()
      return result
    },
    enabled: false,
    initialData,
  })
}
