import {FormControl, Stack, TextInput} from '@primer/react'
import {useId, useState} from 'react'
import * as z from 'zod'

import {FormValidationNode} from '@github-ui/copilot-byok-settings/components/FormValidationNode'
import styles from '../../AddApiKeyDialog.module.css'
import type {ProviderDataFor} from '@github-ui/copilot-byok-settings/types'
import {ProviderModelSelectorPane} from '../ProviderModelSelectorPane'
import type {ProviderFieldProps} from '../types'

export function openAICompatibleFormSchemaPreprocessor(payload: Record<string, unknown>) {
  const providerData: Record<string, unknown> = {}
  if ('base_url' in payload && typeof payload.base_url === 'string' && payload.base_url.trim().length > 0) {
    providerData.base_url = payload.base_url.trim()
  }
  payload.provider_data = providerData
  return payload
}
export const openAICompatibleFormSchema = {
  provider: z.literal('openaicompatible'),
  provider_data: z.object({base_url: z.url('Base API URL must be a valid URL.')}).optional(),
  models: z
    .array(
      z.union([
        z.object({
          id: z.number(),
          name: z.string().nullish(),
        }),
        z.object({
          slug: z.string(),
          name: z.string().nullish(),
        }),
      ]),
    )
    .min(1, 'Please select a model'),
} as const

export function OpenAICompatibleFields({
  apiKey,
  customKey,
  validation,
  isPending,
  setValidation,
  onSetAdditionalData,
  enterpriseSlug,
}: ProviderFieldProps<'openaicompatible'>) {
  const id = useId()
  const [baseUrl, setBaseUrl] = useState(customKey?.baseUrl || '')
  const baseUrlValidationId = `base_url-validation-${id}`
  const modelsValidationId = `models-validation-${id}`

  const providerData: ProviderDataFor<'openaicompatible'> = {
    provider: 'openaicompatible',
    baseUrl: baseUrl || '',
  }

  return (
    <>
      <FormControl required disabled={isPending}>
        <FormControl.Label>Base API URL</FormControl.Label>
        <TextInput
          name="base_url"
          data-1p-ignore
          className="width-full"
          autoComplete="off"
          aria-describedby={baseUrlValidationId}
          value={baseUrl || ''}
          onChange={e => setBaseUrl(e.currentTarget.value)}
        />
        <FormValidationNode
          item={validation ? validation['provider_data.base_url'] : undefined}
          id={baseUrlValidationId}
        />
      </FormControl>

      <Stack.Item grow className={styles.ModelSelectorLayout}>
        <FormControl disabled={isPending} className="width-full">
          <FormControl.Label>Available models</FormControl.Label>
          <ProviderModelSelectorPane
            provider="openaicompatible"
            apiKey={apiKey}
            key={`openaicompatible-${apiKey}`}
            customKeyId={customKey?.id}
            isPending={isPending}
            setValidation={setValidation}
            onSetAdditionalData={onSetAdditionalData}
            aria-describedby={modelsValidationId}
            canAddModels
            enterpriseSlug={enterpriseSlug}
            providerData={providerData}
          />
          <FormValidationNode item={validation?.models} id={modelsValidationId} />
        </FormControl>
      </Stack.Item>
    </>
  )
}
