import {AiModelIcon, CheckIcon, PlusIcon, SearchIcon, XIcon} from '@primer/octicons-react'
import {FormControl, IconButton, Spinner, Stack, TextInput, VisuallyHidden} from '@primer/react'
import {Blankslate} from '@primer/react/experimental'
import {clsx} from 'clsx'
import {type PropsWithChildren, useCallback, useDeferredValue, useId, useMemo, useRef, useState} from 'react'
import invariant from 'tiny-invariant'

import {useCurrentCallback} from '@github-ui/copilot-byok-settings/hooks/use-current-callback'
import type {SelectorCustomModel} from '@github-ui/copilot-byok-settings/types'
import {ModelSelectorConfig} from '@github-ui/copilot-byok-settings/components/ModelSelectorConfig'
import styles from './ModelSelectorPane.module.css'

export function ModelSelectorPane({
  loading = false,
  create = false,
  models,
  selected,
  onSelect,
  disabled,
  htmlForId,
  onCreate,
  'aria-describedby': ariaDescribedBy,
}: {
  models: SelectorCustomModel[]
  selected: Set<SelectorCustomModel['slug']>
  onSelect?: (selected: boolean, model: SelectorCustomModel) => void
  loading?: boolean
  create?: boolean
  disabled?: boolean
  htmlForId?: string
  onCreate?: (modelId: string) => undefined | string
  'aria-describedby'?: string
}) {
  const id = useId()
  const searchFieldDescriptionId = `${id}-search-field-description`
  const listId = `${id}-list`

  const isEmpty = !models.length || loading

  invariant(isEmpty || onSelect, 'onSelect must be provided if items are not empty')
  invariant(create !== true || onCreate, 'onCreate must be provided if create is true')

  // Note; ModelSelectorConfig makes use of React.memo, and unstable callbacks would be a deopt
  // so we use useCurrentCallback here to ensure that the callbacks are stable.
  const onSelectHandler = useCurrentCallback(onSelect)

  const [filter, setFilter] = useState('')
  const deferredFilter = useDeferredValue(filter)
  const filteredModels = useMemo(() => {
    if (!deferredFilter.trim().length) return models
    const filterValue = deferredFilter.toLowerCase()
    return models.filter(model => {
      return model.name?.toLowerCase().includes(filterValue) || model.slug.includes(filterValue)
    })
  }, [models, deferredFilter])

  const [inCreateMode, setInCreateMode] = useState(false)

  return (
    <div
      className={clsx(styles.ModelSelectorPane, {
        [styles.ModelSelectorPaneEmpty]: isEmpty,
      })}
    >
      <div className={styles.ModelSelectorBody}>
        {isEmpty ? (
          <>
            {/* eslint-disable-next-line @typescript-eslint/no-non-null-assertion */}
            {create && <CreateModelID onCreate={onCreate!} aria-describedby={ariaDescribedBy} canCancel={false} />}
            <ModelSelectorPaneBlankslate loading={loading} create={create} />
          </>
        ) : (
          <>
            {create && inCreateMode ? (
              <CreateModelID
                // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
                onCreate={onCreate!}
                onCancel={() => {
                  setInCreateMode(false)
                  setFilter('')
                }}
                aria-describedby={ariaDescribedBy}
              />
            ) : (
              <Stack direction="horizontal" gap="condensed" align="center" className="width-full">
                <SearchField
                  htmlForId={htmlForId}
                  listId={listId}
                  onChange={setFilter}
                  aria-describedby={`${searchFieldDescriptionId} ${ariaDescribedBy}`}
                />
                {create && (
                  <IconButton
                    icon={PlusIcon}
                    variant="default"
                    size="medium"
                    aria-label="Create"
                    aria-describedby={ariaDescribedBy}
                    onClick={() => setInCreateMode(true)}
                  />
                )}
              </Stack>
            )}
            <div className={styles.ModelSelectorList} role="group" aria-labelledby={ariaDescribedBy} id={listId}>
              {filteredModels.length === 0 && <FallbackUI>Nothing matches your search.</FallbackUI>}
              {filteredModels.map(model => (
                <ModelSelectorConfig
                  key={model.slug}
                  model={model}
                  onSelect={onSelectHandler}
                  selected={selected.has(model.slug)}
                  disabled={disabled}
                />
              ))}
            </div>
          </>
        )}
      </div>
    </div>
  )
}

function SearchField({
  htmlForId,
  listId,
  onChange,
  'aria-describedby': ariaDescribedBy,
}: {
  htmlForId?: string
  listId: string
  'aria-describedby'?: string
  onChange: (value: string) => void
}) {
  const id = useId()

  return (
    <>
      <TextInput
        type="search"
        onChange={e => onChange(e.currentTarget.value)}
        placeholder="Search"
        leadingVisual={SearchIcon}
        id={htmlForId}
        aria-controls={listId}
        aria-label="Search models"
        aria-describedby={`${id} ${ariaDescribedBy}`}
        className="width-full"
      />
      <VisuallyHidden id={id}>Models will be filtered as you type.</VisuallyHidden>
    </>
  )
}

function CreateModelID({
  canCancel = true,
  onCreate,
  onCancel,
  'aria-describedby': ariaDescribedBy,
}: {
  'aria-describedby'?: string
  canCancel?: boolean
  onCreate: (modelId: string) => string | undefined
  onCancel?: () => void
}) {
  const fieldRef = useRef<HTMLInputElement>(null)
  const [validation, setValidation] = useState<string | undefined>()

  const handleCreate = useCallback(() => {
    const modelId = fieldRef.current?.value
    if (modelId) {
      const result = onCreate(modelId)
      setValidation(result)
      if (result == null && fieldRef.current) {
        fieldRef.current.value = ''
      }
    }
  }, [onCreate])

  const handleKeyDown = useCallback(
    (event: React.KeyboardEvent<HTMLInputElement>) => {
      if (event.target !== fieldRef.current) return

      // eslint-disable-next-line @github-ui/ui-commands/no-manual-shortcut-logic
      switch (event.key) {
        case 'Enter':
          {
            event.preventDefault()
            handleCreate()
          }
          break
        case 'Escape': {
          event.preventDefault()
          onCancel?.()
        }
      }
    },
    [handleCreate, onCancel],
  )

  return (
    <Stack direction="horizontal" gap="condensed" align="start" className="width-full">
      <div className="width-full">
        <TextInput
          ref={fieldRef}
          onKeyDown={handleKeyDown}
          placeholder="Model ID"
          aria-label="Add model ID"
          aria-describedby={ariaDescribedBy}
          className="width-full"
          size="medium"
        />
        {validation && <FormControl.Validation variant="error">{validation}</FormControl.Validation>}
      </div>
      {canCancel && (
        <IconButton
          icon={XIcon}
          variant="default"
          size="medium"
          aria-label="Cancel create"
          aria-describedby={ariaDescribedBy}
          onClick={onCancel}
        />
      )}
      <IconButton
        icon={CheckIcon}
        variant="default"
        size="medium"
        aria-label="Add model"
        aria-describedby={ariaDescribedBy}
        onClick={handleCreate}
      />
    </Stack>
  )
}

function FallbackUI({children}: PropsWithChildren) {
  return (
    <Blankslate>
      <Blankslate.Description>{children}</Blankslate.Description>
    </Blankslate>
  )
}

function ModelSelectorPaneBlankslate({loading, create}: {loading: boolean; create: boolean}) {
  const description = create ? 'Add a model by ID' : 'Add a valid key to see available models'

  return (
    <Blankslate>
      <Blankslate.Visual>{loading ? <Spinner size="small" /> : <AiModelIcon size="small" />}</Blankslate.Visual>
      <Blankslate.Description>{loading ? 'Loading...' : description}</Blankslate.Description>
    </Blankslate>
  )
}
