import {getQueryClient} from '@github-ui/react-core/query-client'
import {produce} from 'immer'
import {useCallback, useEffect, useMemo} from 'react'

import {isValidModelId} from '@github-ui/copilot-byok-settings/helpers/model-id-schema'
import type {ValidationKind} from '@github-ui/copilot-byok-settings/helpers/validation'
import {useFetchProviderModels} from '../../queries/use-fetch-provider-models'
import type {ProviderDataFor, SelectorCustomModel} from '@github-ui/copilot-byok-settings/types'
import {ModelSelectorPane} from '../ModelSelectorPane'
import type {ProviderFieldProps} from './types'
import type {Provider} from '@github-ui/copilot-byok/providers'

type ProviderModelSelectorPaneProps<P extends Provider = Provider> = ProviderFieldProps<P> & {
  provider: P
  htmlForId?: string
  'aria-describedby'?: string
  customKeyId?: number
  providerData?: ProviderDataFor<P>
  enterpriseSlug: string
}

export function ProviderModelSelectorPane({
  provider,
  customKeyId,
  providerData,
  apiKey,
  isPending: disabled,
  htmlForId,
  'aria-describedby': ariaDescribedBy,
  onSetAdditionalData,
  canAddModels,
  setValidation,
  enterpriseSlug,
}: ProviderModelSelectorPaneProps) {
  // If we have a customKey, always fetch models
  //   and if not, only fetch if we have an apiKey
  const shouldLoadModels = customKeyId != null || !!apiKey
  const {
    error,
    data: models,
    isFetching,
    queryKey,
  } = useFetchProviderModels({
    apiKey,
    provider,
    customKeyId,
    providerData,
    enabled: shouldLoadModels,
    enterpriseSlug,
  })

  const selectedModels = useMemo(() => {
    return new Set(models.flatMap(m => (m.selected ? [m.slug] : [])))
  }, [models])

  const onSelect = useCallback(
    (selected: boolean, model: SelectorCustomModel) => {
      getQueryClient().setQueryData<SelectorCustomModel[]>(
        queryKey,
        produce(prev => {
          if (!prev) return prev
          const maybeModel = prev.find(m => m.slug === model.slug)
          if (maybeModel) {
            maybeModel.selected = selected
          }
        }),
      )
    },
    [queryKey],
  )

  const onAddModel = useCallback(
    (slug: string) => {
      const isValidModelSlug = isValidModelId(slug, models)
      if (isValidModelSlug != null) return isValidModelSlug

      getQueryClient().setQueryData<SelectorCustomModel[]>(
        queryKey,
        produce(prev => {
          if (!prev) return prev
          const newModel: SelectorCustomModel = {
            slug,
            selected: true,
          }
          prev.push(newModel)
          return prev
        }),
      )
    },
    [queryKey, models],
  )

  useEffect(() => {
    onSetAdditionalData({models: models.filter(m => selectedModels.has(m.slug))})
  }, [models, selectedModels, onSetAdditionalData])

  useEffect(() => {
    setValidation((prev: Record<string, ValidationKind> | undefined) => {
      if (error) {
        // Set api_key validation error, preserving other validation errors
        return {...prev, api_key: {error: error.message}}
      } else {
        // Clear api_key validation error, but keep other validation errors
        if (!prev || !prev.api_key) return prev
        const {api_key, ...rest} = prev
        return Object.keys(rest).length > 0 ? rest : undefined
      }
    })
  }, [error, setValidation])

  return (
    <ModelSelectorPane
      models={models}
      selected={selectedModels}
      loading={isFetching}
      onSelect={onSelect}
      disabled={disabled}
      htmlForId={htmlForId}
      aria-describedby={ariaDescribedBy}
      create={canAddModels}
      onCreate={onAddModel}
    />
  )
}
